CREATE TABLE public.embed_views (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, layout text NOT NULL, theme text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.embed_views TO authenticated; GRANT ALL ON public.embed_views TO service_role; ALTER TABLE public.embed_views ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners read their embed views" ON public.embed_views FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = embed_views.profile_id AND p.user_id = auth.uid())); CREATE INDEX embed_views_profile_created_idx ON public.embed_views (profile_id, created_at DESC);